matrix_mult_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matrix_mult_kernel(const float* A, const float* B, float* C, int N) {
    // Define tile size
    const int TILE_SIZE = 16;

    // Shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Thread indices
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile from A into shared memory
        int tiled_row = threadIdx.y;
        int tiled_col = t * TILE_SIZE + threadIdx.x;
        if (row < N && tiled_col < N) {
            As[tiled_row][threadIdx.x] = A[row * N + tiled_col];
        } else {
            As[tiled_row][threadIdx.x] = 0.0f;
        }

        // Load tile from B into shared memory
        tiled_row = t * TILE_SIZE + threadIdx.y;
        tiled_col = col;
        if (tiled_row < N && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[tiled_row * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Synchronize to ensure all tiles are loaded
        __syncthreads();

        // Compute partial sum for this tile
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += As[tiled_row][k] * Bs[k][threadIdx.x];
        }

        // Synchronize before loading next tiles
        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matrix_mult_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    // Use 16x16 threads per block
    dim3 threadsPerBlock(16, 16);
    dim3 numBlocks((N + threadsPerBlock.x - 1) / threadsPerBlock.x, 
                   (N + threadsPerBlock.y - 1) / threadsPerBlock.y);

    matrix_mult_kernel<<<numBlocks, threadsPerBlock>>>(A.data_ptr<float>(), 
                                                      B.data_ptr<float>(), 
                                                      C.data_ptr<float>(), 
                                                      N);
    return C;
}
"""

